import { siteConfig } from '../config/site'
import { motion } from 'framer-motion'
import { MapPin, Sparkles } from 'lucide-react'

export default function Hero() {
  const { hero } = siteConfig

  return (
    <section className="relative min-h-[90vh] flex items-center overflow-hidden">
      {/* Background pattern */}
      <div className="absolute inset-0 bg-cream">
        <div className="absolute top-20 right-0 w-[600px] h-[600px] bg-sage/20 rounded-full blur-3xl" />
        <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-warm-orange/15 rounded-full blur-3xl" />
        <div className="absolute top-1/3 left-1/4 w-[300px] h-[300px] bg-forest/5 rounded-full blur-2xl" />
      </div>

      {/* Floating decorative elements */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <motion.div
          className="absolute top-[15%] right-[15%] text-6xl"
          animate={{ y: [0, -15, 0], rotate: [0, 5, 0] }}
          transition={{ duration: 5, repeat: Infinity, ease: "easeInOut" }}
        >
          🍋
        </motion.div>
