import { useRef, useState } from 'react'
import { siteConfig } from '../config/site'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { motion } from 'framer-motion'

export default function FeaturedProducts() {
  const scrollRef = useRef<HTMLDivElement>(null)
  const [canScrollLeft, setCanScrollLeft] = useState(false)
  const [canScrollRight, setCanScrollRight] = useState(true)

  const checkScroll = () => {
    if (!scrollRef.current) return
    const { scrollLeft, scrollWidth, clientWidth } = scrollRef.current
    setCanScrollLeft(scrollLeft > 10)
    setCanScrollRight(scrollLeft + clientWidth < scrollWidth - 10)
  }

  const scroll = (direction: 'left' | 'right') => {
    if (!scrollRef.current) return
    const cardWidth = 280
    const scrollAmount = direction === 'left' ? -cardWidth * 2 : cardWidth * 2
    scrollRef.current.scrollBy({ left: scrollAmount, behavior: 'smooth' })
    setTimeout(checkScroll, 400)
  }

  return (
    <section id="featured-products" className="py-20 sm:py-28 bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-end justify-between mb-12">
          <div>
            <span className="text-forest font-semibold text-sm uppercase tracking-wider">Staff Favorites</span>
            <h2 className="font-heading font-800 text-3xl sm:text-4xl text-forest-dark mt-2">
              Featured Products
            </h2>
          </div>
          <div className="hidden sm:flex gap-2">
            <button
              onClick={() => scroll('left')}
              disabled={!canScrollLeft}
              className="w-11 h-11 rounded-xl border-2 border-forest/20 flex items-center justify-center hover:bg-forest hover:text-white hover:border-forest transition-all disabled:opacity-30 disabled:hover:bg-transparent disabled:hover:text-forest-dark text-forest-dark"
              aria-label="Scroll left"
            >
              <ChevronLeft className="w-5 h-5" />
            </button>
            <button
