export default function SeasonalPicks() {
  const { seasonalPicks } = siteConfig

  return (
    <section className="py-20 sm:py-28 bg-forest-dark relative overflow-hidden">
      {/* Decorative background */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-10 right-10 text-[120px] opacity-10 rotate-12">☀️</div>
        <div className="absolute bottom-10 left-10 text-[100px] opacity-10 -rotate-12">🍉</div>
      </div>

