import { siteConfig } from '../config/site'
import { motion } from 'framer-motion'

export default function Categories() {
  return (
    <section className="py-20 sm:py-28 bg-cream">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-14">
          <span className="text-forest font-semibold text-sm uppercase tracking-wider">Browse Aisles</span>
          <h2 className="font-heading font-800 text-3xl sm:text-4xl text-forest-dark mt-2">
            Shop by Category
          </h2>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4 sm:gap-5">
          {siteConfig.categories.map((cat, i) => (
            <motion.div
              key={cat.name}
              className="relative group cursor-pointer rounded-2xl overflow-hidden aspect-[4/5]"
              initial={{ opacity: 0, scale: 0.9 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ duration: 0.4, delay: i * 0.08 }}
            >
              {/* Background */}
              <div
                className="absolute inset-0 transition-transform duration-500 group-hover:scale-110"
                style={{ backgroundColor: cat.color + '60' }}
              />

              {/* Emoji icon */}
              <div className="absolute inset-0 flex items-center justify-center">
                <span className="text-6xl sm:text-7xl group-hover:scale-125 transition-transform duration-500">
                  {cat.emoji}
                </span>
              </div>

              {/* Hover overlay */}
              <div className="absolute inset-0 bg-forest-dark/0 group-hover:bg-forest-dark/70 transition-all duration-300 flex items-center justify-center">
                <div className="text-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 translate-y-4 group-hover:translate-y-0 transform">
                  <h3 className="font-heading font-700 text-white text-lg mb-1">
                    {cat.name}
                  </h3>
                  <p className="text-sage text-xs leading-snug px-3">
                    {cat.description}
                  </p>
                </div>
              </div>

              {/* Always-visible label at bottom */}
              <div className="absolute bottom-0 left-0 right-0 p-3 bg-gradient-to-t from-black/40 to-transparent group-hover:opacity-0 transition-opacity duration-300">
                <p className="font-heading font-700 text-white text-sm">
                  {cat.name}
                </p>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  )
}

