import { siteConfig } from '../config/site'
import { motion } from 'framer-motion'
import { MapPin, Package, Tag, CalendarDays } from 'lucide-react'

const icons = [MapPin, Package, Tag, CalendarDays]

export default function BrandHighlights() {
  return (
    <section className="py-16 sm:py-20 bg-white relative overflow-hidden">
      {/* Subtle pattern */}
      <div className="absolute inset-0 opacity-5">
        <div className="absolute inset-0" style={{
          backgroundImage: 'radial-gradient(circle, #2D6A4F 1px, transparent 1px)',
          backgroundSize: '24px 24px',
        }} />
      </div>

      <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-6 sm:gap-8">
          {siteConfig.brandHighlights.map((item, i) => {
            const Icon = icons[i]
            return (
              <motion.div
                key={item.label}
                className="text-center"
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.4, delay: i * 0.1 }}
              >
                <div className="inline-flex items-center justify-center w-14 h-14 rounded-2xl bg-forest/10 text-forest mb-4">
                  <Icon className="w-7 h-7" />
                </div>
                <div className="font-heading font-900 text-4xl sm:text-5xl text-forest-dark mb-1">
                  {item.stat}
                </div>
                <div className="font-heading font-700 text-forest text-sm mb-1">
                  {item.label}
                </div>
                <p className="text-gray-500 text-xs leading-relaxed max-w-[200px] mx-auto">
                  {item.description}
                </p>
              </motion.div>
            )
          })}
        </div>
      </div>
    </section>
  )
}

