import { useState } from 'react'
import { siteConfig } from '../config/site'
import { Search, MapPin, Clock, Navigation } from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'

export default function StoreLocator() {
  const [zip, setZip] = useState('')
  const [searched, setSearched] = useState(false)
  const { storeLocator } = siteConfig

  const handleSearch = () => {
    if (zip.trim()) setSearched(true)
  }

  return (
    <section id="store-locator" className="py-20 sm:py-28 bg-cream">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="max-w-2xl mx-auto text-center">
          <span className="text-forest font-semibold text-sm uppercase tracking-wider">Visit Us</span>
          <h2 className="font-heading font-800 text-3xl sm:text-4xl text-forest-dark mt-2 mb-4">
            {storeLocator.title}
          </h2>
          <p className="text-gray-600 text-lg mb-8">
            {storeLocator.subtitle}
          </p>

          {/* Search input */}
          <div className="flex gap-3 max-w-md mx-auto mb-10">
            <div className="flex-1 relative">
              <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input
                type="text"
                value={zip}
                onChange={(e) => { setZip(e.target.value); setSearched(false) }}
                placeholder={storeLocator.placeholder}
                onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                className="w-full pl-12 pr-4 py-4 rounded-xl border-2 border-forest/15 bg-white text-forest-dark font-medium placeholder:text-gray-400 focus:outline-none focus:border-forest focus:ring-2 focus:ring-forest/10 transition-all"
              />
            </div>
            <button
              onClick={handleSearch}
              className="px-6 py-4 bg-forest text-white rounded-xl font-heading font-700 hover:bg-forest-dark transition-all hover:shadow-lg hover:shadow-forest/25 flex items-center gap-2"
            >
              <Search className="w-5 h-5" />
              <span className="hidden sm:inline">{storeLocator.button}</span>
            </button>
          </div>

          {/* Results */}
          <AnimatePresence>
            {searched && (
              <motion.div
                className="space-y-4"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.4 }}
              >
                <p className="text-sm text-gray-500 mb-6">
                  Showing stores near <span className="font-semibold text-forest-dark">{zip}</span>
                </p>
                {storeLocator.results.map((store, i) => (
                  <motion.div
                    key={store.name}
                    className="bg-white rounded-2xl p-5 sm:p-6 text-left shadow-sm hover:shadow-md transition-shadow border border-forest/5"
                    initial={{ opacity: 0, y: 15 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.3, delay: i * 0.1 }}
                  >
                    <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                      <div className="flex-1">
                        <h3 className="font-heading font-700 text-forest-dark text-base mb-1">
                          {store.name}
                        </h3>
                        <p className="text-gray-500 text-sm">{store.address}</p>
                        <div className="flex items-center gap-4 mt-2">
                          <span className="flex items-center gap-1.5 text-sm text-gray-600">
                            <Clock className="w-4 h-4 text-forest" />
                            {store.hours}
                          </span>
                        </div>
                      </div>
                      <div className="flex items-center gap-3 sm:flex-col sm:items-end">
                        <span className="font-heading font-800 text-warm-orange-dark text-lg">
                          {store.distance}
                        </span>
                        <button className="flex items-center gap-1.5 text-sm font-semibold text-forest hover:text-forest-dark transition-colors">
                          <Navigation className="w-4 h-4" />
                          Directions
                        </button>
                      </div>
                    </div>
                  </motion.div>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </section>
  )
}

