import { motion, AnimatePresence } from 'framer-motion'

export default function Newsletter() {
  const [email, setEmail] = useState('')
  const [subscribed, setSubscribed] = useState(false)
  const { newsletter } = siteConfig

  const handleSubmit = () => {
    if (email.includes('@')) setSubscribed(true)
  }

  return (
    <section className="py-20 sm:py-28 bg-warm-orange relative overflow-hidden">
      {/* Decorative elements */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute -top-10 -left-10 text-[150px] opacity-10 rotate-12">🍋</div>
        <div className="absolute -bottom-10 -right-10 text-[130px] opacity-10 -rotate-12">🍊</div>
      </div>

      <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="max-w-xl mx-auto text-center">
          <h2 className="font-heading font-800 text-3xl sm:text-4xl text-white mb-4">
            {newsletter.title}
          </h2>
          <p className="text-white/80 text-lg mb-8">
            {newsletter.subtitle}
          </p>

          <AnimatePresence mode="wait">
            {!subscribed ? (
              <motion.div
                key="form"
